  const subscription = await subscriptionRepo.updateSubscriptionPlan(
    input.orgId,
    input.plan,
    input.interval,
  );

150→  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return subscription;
}

