export async function setActiveOrg(
  sessionId: SessionId,
  orgId: OrgId,
): Promise<void> {
  getDb()
    .update(sessions)
    .set({ activeOrgId: orgId, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(sessions.id, sessionId))
    .run();
}

/** Drops a closed workspace from every session that still had it selected. */
export async function clearActiveOrg(orgId: OrgId): Promise<void> {
  getDb()
    .update(sessions)
    .set({ activeOrgId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(sessions.activeOrgId, orgId))
    .run();
}

/**
 * Drops every delivery that was still waiting when the workspace closed.
 * Claimed-but-not-yet-delivered rows are included so a queued payload cannot
 * leave after the close.
 */
export async function cancelPendingDeliveries(orgId: OrgId): Promise<number> {
  const rows = getDb()
    .update(webhookDeliveries)
    .set({
      status: "failed",
      lastError: "workspace is closed",
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.status, "pending"),
      ),
    )
    .returning({ id: webhookDeliveries.id })
    .all();

  return rows.length;
}

